import { Link, NavLink, useNavigate } from 'react-router-dom';
import { useAuth } from '../../features/auth/context/AuthContext';
import { ROLES } from '../../utils/constants';
import './Header.css';

export default function Header() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();

  const handleLogout = () => {
    logout();
    navigate('/');
  };

  const isStaff = user && (user.role === ROLES.ADMIN || user.role === ROLES.LIBRARIAN);

  return (
    <header className="site-header">
      <div className="container site-header-inner">
        <Link to="/" className="logo">Smart Library</Link>

        <nav className="header-nav" aria-label="Primary">
          <NavLink to="/books">Books</NavLink>
          <NavLink to="/search">Search</NavLink>
          <NavLink to="/dashboard">Dashboard</NavLink>
          <NavLink to="/borrow">Borrow</NavLink>
          <NavLink to="/profile">Profile</NavLink>
          <NavLink to="/notifications">Notifications</NavLink>
          {isStaff && (
            <span className="header-nav-divider" aria-hidden="true" />
          )}
          {isStaff && <NavLink to="/admin/books">Manage Books</NavLink>}
          {isStaff && <NavLink to="/admin/history">History</NavLink>}
          {isStaff && <NavLink to="/admin/payments">Payments</NavLink>}
          {user && user.role === ROLES.ADMIN && <NavLink to="/admin/users">Users</NavLink>}
        </nav>

        <div className="header-actions">
          {user ? (
            <>
              <span className={`user-role role-${user.role}`}>
                {user.role === ROLES.ADMIN ? 'Admin' : user.role === ROLES.LIBRARIAN ? 'Librarian' : 'Member'}
              </span>
              <button onClick={handleLogout} className="header-logout">Logout</button>
              <Link to="/borrow" className="header-cta">Reserve</Link>
            </>
          ) : (
            <Link to="/login" className="header-cta">Login</Link>
          )}
        </div>
      </div>
    </header>
  );
}
